      try{const result=await request('confirmUpdate',{id,accepted});if(updateConfirmation?.id===id){updateConfirmation=null;confirmationPending=false;syncUpdateConfirmation();syncReleaseNotes();}if(result?.accepted===false)notice='Nexus did not respond. Try again.';}
